mapper.update:
UPDATE habits
SET status = #{newStatus},
    version = #{version} + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND status = #{oldStatus}
  AND version = #{version}

mapper.select:
SELECT *
FROM habits
WHERE user_id = #{userId}
  AND status IN ('ACTIVE', 'PAUSED')
ORDER BY updated_at DESC
LIMIT #{limit}

SELECT *
FROM habits
WHERE user_id = #{userId}
  AND name = #{name}
  AND status IN ('ACTIVE', 'PAUSED')
ORDER BY updated_at DESC
